#include <zephyr/drivers/dac.h>
#include <zephyr/drivers/dac/dac_emul.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/device.h>

LOG_MODULE_REGISTER(dac_emul, CONFIG_DAC_LOG_LEVEL);

#define DT_DRV_COMPAT zephyr_dac_emul

struct dac_emul_data {
    uint32_t *channel_values;
    uint8_t num_channels;
};

struct dac_emul_cfg {
    uint8_t num_channels;
    uint8_t resolution;
};

static int dac_emul_channel_setup(const struct device *dev,
                                  const struct dac_channel_cfg *channel_cfg)
{
    const struct dac_emul_cfg *cfg = dev->config;

    if (channel_cfg->channel_id >= cfg->num_channels) {
        LOG_ERR("Invalid channel ID %d", channel_cfg->channel_id);
        return -EINVAL;
    }

    if (channel_cfg->resolution != cfg->resolution) {
        LOG_ERR("Invalid resolution %d for channel %d (expected %d)",
                channel_cfg->resolution, channel_cfg->channel_id, cfg->resolution);
        return -EINVAL;
    }

    return 0;
}

static int dac_emul_write_value(const struct device *dev, uint8_t channel, uint32_t value)
{
    struct dac_emul_data *data = dev->data;
    const struct dac_emul_cfg *cfg = dev->config;

    if (channel >= cfg->num_channels) {
        LOG_ERR("Invalid channel ID %d", channel);
        return -EINVAL;
    }

    if (value >= (1U << cfg->resolution)) {
        LOG_ERR("Value %d out of range for %d-bit resolution (max %d)",
                value, cfg->resolution, (1U << cfg->resolution) - 1);
        return -EINVAL;
    }

    data->channel_values[channel] = value;
    LOG_DBG("DAC emul %s channel %d set to %d", dev->name, channel, value);

    return 0;
}

uint32_t dac_emul_value_get(const struct device *dev, uint8_t channel)
{
    struct dac_emul_data *data = dev->data;
    const struct dac_emul_cfg *cfg = dev->config;

    if (channel >= cfg->num_channels) {
        LOG_ERR("Invalid channel ID %d", channel);
        return 0;
    }

    return data->channel_values[channel];
}

static const struct dac_driver_api dac_emul_api = {
    .channel_setup = dac_emul_channel_setup,
    .write_value = dac_emul_write_value,
};

#define DAC_EMUL_INIT(inst)                                                                        \
    static uint32_t dac_emul_channel_values_##inst[DT_INST_PROP(inst, num_channels)];              \
    static struct dac_emul_data dac_emul_data_##inst = {                                           \
        .channel_values = dac_emul_channel_values_##inst,                                          \
        .num_channels = DT_INST_PROP(inst, num_channels),                                          \
    };                                                                                             \
    static const struct dac_emul_cfg dac_emul_cfg_##inst = {                                       \
        .num_channels = DT_INST_PROP(inst, num_channels),                                          \
        .resolution = DT_INST_PROP(inst, resolution),                                              \
    };                                                                                             \
    DEVICE_DT_INST_DEFINE(inst, NULL, NULL, &dac_emul_data_##inst, &dac_emul_cfg_##inst,           \
                          POST_KERNEL, CONFIG_DAC_EMUL_INIT_PRIORITY, &dac_emul_api);

DT_INST_FOREACH_STATUS_OKAY(DAC_EMUL_INIT)
